verification_command:
$ErrorActionPreference = 'Stop'
$packetRoot = 'docs/testing/performance/0.74/local-runs/msrv-tooling-trace-cleanup-20261015'
$manifest = Get-Content -Raw -LiteralPath "$packetRoot/manifest.json" | ConvertFrom-Json
$names = @($manifest.captures.file)
if ($names.Count -ne 44 -or @($names | Sort-Object -Unique).Count -ne 44) { throw 'capture inventory' }
$diskNames = @(Get-ChildItem -LiteralPath $packetRoot -File -Filter '*.log' | Select-Object -ExpandProperty Name)
if (@(Compare-Object $names $diskNames).Count -ne 0) { throw 'unlisted raw capture' }
foreach ($entry in @($manifest.captures) + @($manifest.extra_artifacts)) {
    if ((Split-Path -Leaf $entry.file) -cne $entry.file) { throw 'artifact basename' }
    $artifact = Get-Item -LiteralPath "$packetRoot/$($entry.file)"
    $digest = (Get-FileHash -LiteralPath $artifact.FullName -Algorithm SHA256).Hash.ToLowerInvariant()
    if ($digest -cne $entry.sha256 -or $artifact.Length -ne $entry.bytes) { throw "artifact changed: $($entry.file)" }
}
foreach ($entry in @($manifest.frozen_files) + @($manifest.preserved_negatives)) {
    if ((Get-FileHash -LiteralPath $entry.path -Algorithm SHA256).Hash.ToLowerInvariant() -cne $entry.sha256) { throw "frozen input changed: $($entry.path)" }
}
$tree = git rev-parse "$($manifest.source_commit)^{tree}"
if ($LASTEXITCODE -ne 0 -or $tree -cne $manifest.source_tree) { throw 'source tree' }
foreach ($entry in $manifest.source_files) {
    $blob = git rev-parse "$($manifest.source_commit):$($entry.path)"
    if ($LASTEXITCODE -ne 0 -or $blob -cne $entry.git_blob) { throw 'source blob' }
}
$formatParent = git rev-parse "$($manifest.format_commit)^"
$traceParent = git rev-parse "$($manifest.trace_commit)^"
if ($formatParent -cne $manifest.baseline_commit -or $traceParent -cne $manifest.format_commit -or $manifest.trace_commit -cne $manifest.source_commit) { throw 'source chain' }
$changed = @(git diff --name-only $manifest.baseline_commit $manifest.source_commit -- crates tools)
if ($LASTEXITCODE -ne 0 -or $changed.Count -ne 10 -or @(Compare-Object $changed @($manifest.source_files.path)).Count -ne 0) { throw 'source inventory' }
$rewriteData = Get-Content -Raw -LiteralPath "$packetRoot/source-rewrites.json" | ConvertFrom-Json
if ($rewriteData.baseline -cne $manifest.baseline_commit) { throw 'rewrite baseline' }
$transformCount = 0
foreach ($source in $rewriteData.format_sources) {
    $old = (git show "$($manifest.baseline_commit):$($source.path)") -join "`n"
    if ($LASTEXITCODE -ne 0) { throw 'old format source' }
    $new = (git show "$($manifest.source_commit):$($source.path)") -join "`n"
    if ($LASTEXITCODE -ne 0) { throw 'new format source' }
    if ($source.marker) {
        $oldCut = $old.IndexOf($source.marker)
        $newCut = $new.IndexOf($source.marker)
        if ($oldCut -lt 0 -or $newCut -lt 0) { throw 'test boundary' }
        $old = $old.Substring(0, $oldCut)
        $new = $new.Substring(0, $newCut)
    }
    foreach ($rewrite in $source.rewrites) {
        if ([regex]::Matches($old, [regex]::Escape($rewrite.before)).Count -ne 1) { throw 'nonunique format rewrite' }
        $old = $old.Replace($rewrite.before, $rewrite.after)
        $transformCount++
    }
    if ($old.TrimEnd() -cne $new.TrimEnd()) { throw 'unregistered format source change' }
}
if ($transformCount -ne 7) { throw 'format rewrite count' }
$traceSource = $rewriteData.supervisor_source
$old = (git show "$($manifest.baseline_commit):$($traceSource.path)") -join "`n"
if ($LASTEXITCODE -ne 0) { throw 'old trace source' }
$new = (git show "$($manifest.source_commit):$($traceSource.path)") -join "`n"
if ($LASTEXITCODE -ne 0) { throw 'new trace source' }
if (@($traceSource.rewrites).Count -ne 1) { throw 'trace rewrite count' }
foreach ($rewrite in $traceSource.rewrites) {
    if ([regex]::Matches($old, [regex]::Escape($rewrite.before)).Count -ne 1) { throw 'nonunique trace rewrite' }
    $old = $old.Replace($rewrite.before, $rewrite.after)
}
if ($old.TrimEnd() -cne $new.TrimEnd()) { throw 'unregistered trace source change' }
$tracePaths = @(git diff --name-only $manifest.format_commit $manifest.trace_commit)
if ($LASTEXITCODE -ne 0 -or $tracePaths.Count -ne 1 -or $tracePaths[0] -cne $traceSource.path) { throw 'trace-only commit' }
$failedGateFiles = @('baseline-windows-msrv-failed.log', 'baseline-linux-msrv-failed.log', 'after-trace-process-timeout.log')
foreach ($capture in $manifest.captures) {
    if ($failedGateFiles -contains $capture.file) {
        if ($capture.exit_code -ne 1 -or $capture.gate_expected_exit -ne 0) { throw 'failed gate reclassified' }
    } elseif ($capture.file -ceq 'require-ship.log') {
        if ($capture.exit_code -ne 1 -or $capture.gate_expected_exit -ne 1 -or $capture.classification -cne 'expected-closed-admission') { throw 'ship refusal reclassified' }
    } elseif ($capture.exit_code -ne 0 -or $capture.gate_expected_exit -ne 0) { throw 'unexpected capture status' }
}
function Assert-TestTotals($file, $passed, $failed) {
    $captureText = Get-Content -Raw -LiteralPath "$packetRoot/$file"
    $totals = [regex]::Matches($captureText, 'test result: (?:ok|FAILED)\. (\d+) passed; (\d+) failed; (\d+) ignored;')
    $passedTotal = 0
    $failedTotal = 0
    foreach ($total in $totals) {
        $passedTotal += [int]$total.Groups[1].Value
        $failedTotal += [int]$total.Groups[2].Value
        if ([int]$total.Groups[3].Value -ne 0) { throw 'unreported ignored test' }
    }
    if ($totals.Count -eq 0 -or $passedTotal -ne $passed -or $failedTotal -ne $failed) { throw "test totals: $file" }
}
Assert-TestTotals 'baseline-supervisor.log' 67 0
Assert-TestTotals 'after-trace-process-timeout.log' 66 1
Assert-TestTotals 'control-original-trace-process.log' 67 0
Assert-TestTotals 'repeat-trace-process.log' 67 0
Assert-TestTotals 'postcommit-trace-process.log' 67 0
Assert-TestTotals 'after-format-metrics.log' 7 0
Assert-TestTotals 'after-format-csv.log' 22 0
Assert-TestTotals 'after-format-pure-client.log' 4 0
Assert-TestTotals 'after-format-xtask.log' 27 0
Assert-TestTotals 'performance-contract-tests.log' 165 0
if ((Get-Content -Raw -LiteralPath "$packetRoot/gate-registry.log") -notmatch '175 discovered gates, all registered') { throw 'registry total' }
if ((Get-Content -Raw -LiteralPath "$packetRoot/local-contract.log") -notmatch 'OK \(local, non-promotable\)') { throw 'local contract classification' }
Write-Output 'Verified 44 complete captures, 2 extra artifacts, 10 source blobs/tree/parent chain, 7 exact format rewrites, 1 whole-file trace rewrite and frozen inputs/negative hashes.'
Write-Output 'Verified test totals and retained three actual-exit1/expected-exit0 failed gates. Require-ship alone is an expected refusal. Original trace passes twice; trace candidate fails 66/1 once and later passes 67 twice. The timeout cause and load robustness remain open.'
Write-Output 'Unsigned consistency only: not execution attestation, runtime support, performance evidence, authenticated original-start, all-writer cessation or server admission.'
